/// Server to all, event `phase:start`. Identical for every player, so a phone screen gives
/// nothing away. Clients compare serverNow to their own clock and shift endsAt by the
/// difference, so countdowns stay within 1 second.
// MARK: - PhaseStart
public struct PhaseStart: Codable, Equatable {
    /// When the phase ends, in server time.
    public let endsAt: Int
    public let phase: Phase
    public let round: Int
    /// Server time when the event was sent. Clients use it to correct their own clock.
    public let serverNow: Int

    public init(endsAt: Int, phase: Phase, round: Int, serverNow: Int) {
        self.endsAt = endsAt
        self.phase = phase
        self.round = round
        self.serverNow = serverNow
    }
}

