        try self.init(data: try Data(contentsOf: url))
    }

    func with(
        endsAt: Int? = nil,
        phase: Phase? = nil,
        round: Int? = nil,
        serverNow: Int? = nil
    ) -> PhaseStart {
        return PhaseStart(
            endsAt: endsAt ?? self.endsAt,
