/// Server to one, event `you:result`. Private result of the player's Day action, sent when
/// Day ends. Blocked and faked results look exactly like normal ones. Client text: Search
/// null = "You found nothing", Commune null = "The dead are silent", Candle blocked = "The
/// Monster blocked your candle".
// MARK: - YouResult
public struct YouResult: Codable, Equatable {
    public let action: DayAction
    /// Candle only. Sent as false for a normal candle so every Candle gets a result. A save
    /// itself is never reported.
    public let candleBlocked: Bool?
    public let round: Int
    /// Search and Commune only. Search: a trait the Monster has. Commune: a trait the Monster
    /// does not have. Null when nothing was found.
    public let trait: Trait?

    public init(action: DayAction, candleBlocked: Bool?, round: Int, trait: Trait?) {
        self.action = action
        self.candleBlocked = candleBlocked
        self.round = round
        self.trait = trait
    }
}

